<?php
namespace EventFlow\Infrastructure\Export;
use EventFlow\Application\Export\{ExportDataSource,ExportRecord,ExportType};use EventFlow\Infrastructure\Persistence\TableName;use EventFlow\Infrastructure\Persistence\WordPress\{WpdbAdapter,WpdbTableNames};
final readonly class WpdbExportDataSource implements ExportDataSource
{
 public function __construct(private WpdbAdapter $db,private WpdbTableNames $names){}
 public function rows(ExportRecord $e):iterable{$limit=500;$cursor=0;$table=match($e->type){ExportType::ATTENDEES=>TableName::ATTENDEES,ExportType::INVITATIONS=>TableName::INVITATIONS,ExportType::CHECK_INS=>TableName::CHECKINS,ExportType::EVENT_SUMMARY=>TableName::EVENTS};$id=match($e->type){ExportType::ATTENDEES=>'attendee_id',ExportType::INVITATIONS=>'invitation_id',ExportType::CHECK_INS=>'checkin_id',ExportType::EVENT_SUMMARY=>'event_id'};$columns=match($e->type){ExportType::ATTENDEES=>'attendee_id,invitation_id,display_name,attendee_role,attendance_status,email,phone,dietary_requirements,accessibility_requirements,created_at',ExportType::INVITATIONS=>'invitation_id,invitation_code,primary_name,primary_email,primary_phone,capacity,invitation_status,response_status,created_at',ExportType::CHECK_INS=>'checkin_id,attendee_id,station_id,action_type,checkin_method,reversal_of_checkin_id,reason,occurred_at,created_at',ExportType::EVENT_SUMMARY=>'event_id,event_name,event_status,starts_at,ends_at,timezone,created_at'};do{$rows=$this->db->fetchAll('SELECT '.$columns.' FROM '.$this->names->get($table).' WHERE event_id = %d AND '.$id.' > %d AND created_at <= %s ORDER BY '.$id.' ASC LIMIT %d',[$e->eventScope->eventId,$cursor,$e->cutoffAt->format('Y-m-d H:i:s'),$limit]);foreach($rows as$row){$cursor=(int)$row[$id];yield $row;}}while(count($rows)===$limit);}
}
